namespace Shared.Domain;

/// <summary>
/// Turns a <c>sealed partial record</c> into a parsed string type. The type declares only
/// <c>private static TSelf? TryParse(string value)</c>, which returns <c>null</c> for invalid
/// input and otherwise normalizes and constructs the value through the generated private
/// constructor. Everything else (the constructor, <c>Parse</c>, the public <c>TryParse</c>,
/// <c>ToString</c>, <see cref="IParsedString{TSelf}"/> and the JSON converter) is generated by
/// Shared.Domain.Generators.
/// </summary>
/// <param name="pattern">A regular expression every valid value matches, shown to API consumers.</param>
/// <param name="example">A valid value, shown in Swagger UI and in parse error messages.</param>
[AttributeUsage(AttributeTargets.Class, Inherited = false)]
public sealed class ParsedStringAttribute(string pattern, string example) : Attribute
{
    public string Pattern { get; } = pattern;

    public string Example { get; } = example;
}
